import React, {
    FocusEventHandler,
    FunctionComponent,
    useCallback,
    useMemo,
} from 'react';
import { defineMessages } from 'react-intl';
import { NumericFormat } from 'react-number-format';
import { useSafeIntl } from '../../../localization/useSafeIntl';
import { getCurrencyAffixes } from '../../../utils/currency';
import { CustomInput } from './Input';

const MESSAGES = defineMessages({
    max: {
        id: 'blsq.numberInput.error.max',
        defaultMessage: 'Input exceeds {value}',
    },
    min: {
        id: 'blsq.numberInput.error.min',
        defaultMessage: 'Input is less than {value}',
    },
    invalid: {
        id: 'blsq.numberInput.error.invalid',
        defaultMessage: 'Invalid number',
    },
});

type Props = {
    keyValue: string;
    errors?: string[];
    value?: string | number;
    label?: string;
    required?: boolean;
    disabled?: boolean;
    multiline?: boolean;
    autoComplete?: string;
    min?: number;
    max?: number;
    onChange: (newValue: number | undefined) => void;
    onBlur?: FocusEventHandler<HTMLInputElement | HTMLTextAreaElement>;
    onFocus?:
        | FocusEventHandler<HTMLInputElement | HTMLTextAreaElement>
        | undefined;
    prefix?: string;
    suffix?: string;
    currency?: string;
    decimalScale?: number;
    placeholder?: string;
    setFieldError?: (
        keyValue: string,

        message: string,
    ) => void;
    thousandsGroupStyle?: 'thousand' | 'lakh' | 'wan';
    thousandSeparator?: ',' | '.';
    decimalSeparator?: ',' | '.';
    dataTestId?: string;
    size?: 'small' | 'medium';
    showArrows?: boolean;
    showInfo?: boolean;
    step?: number;
    hideError?: boolean;
};

const clamp = (value: number, min: number, max: number): number =>
    Math.min(Math.max(value, min), max);

const getSteppedValue = (
    value: string | number,
    step: number,
    min: number,
    max: number,
): number => {
    const currentValue = Number(value);
    if (value === '' || value === null || Number.isNaN(currentValue)) {
        return Number.isFinite(min) ? min : clamp(0, min, max);
    }
    const nextValue = Number((currentValue + step).toPrecision(15));
    return clamp(nextValue, min, max);
};

export const NumberInput: FunctionComponent<Props> = ({
    keyValue,
    label,
    onChange,
    onBlur,
    onFocus,
    placeholder,
    dataTestId,
    errors = [],
    required = false,
    value = '',
    disabled = false,
    multiline = false,
    autoComplete = 'off',
    min = -Infinity,
    max = Infinity,
    prefix = '',
    suffix = '',
    currency,
    decimalScale = 10,
    setFieldError = () => null,
    thousandsGroupStyle = 'thousand',
    thousandSeparator = ',',
    decimalSeparator = '.',
    size = 'medium',
    showArrows = false,
    showInfo = true,
    step = 1,
    hideError = false,
}) => {
    const { formatMessage } = useSafeIntl();
    const handleChange = useCallback(
        values => {
            const newValueAsNumber = values.floatValue;
            if (
                (newValueAsNumber <= max && newValueAsNumber >= min) ||
                newValueAsNumber === undefined
            ) {
                onChange(newValueAsNumber);
            } else if (newValueAsNumber > max) {
                setFieldError(
                    keyValue,
                    formatMessage(MESSAGES.max, {
                        value: max.toString(),
                    }) as string,
                );
            } else if (newValueAsNumber < min) {
                setFieldError(
                    keyValue,
                    formatMessage(MESSAGES.min, {
                        value: min.toString(),
                    }) as string,
                );
            } else if (Number.isNaN(newValueAsNumber) && required) {
                setFieldError(
                    keyValue,
                    formatMessage(MESSAGES.invalid) as string,
                );
            }
        },
        [max, min, required, onChange, setFieldError, keyValue, formatMessage],
    );
    const handleIncrement = useCallback(
        () => onChange(getSteppedValue(value, step, min, max)),
        [onChange, value, step, min, max],
    );
    const handleDecrement = useCallback(
        () => onChange(getSteppedValue(value, -step, min, max)),
        [onChange, value, step, min, max],
    );
    const currencyAffixes = useMemo(
        () => (currency ? getCurrencyAffixes(currency) : undefined),
        [currency],
    );
    return (
        <NumericFormat
            value={value}
            disabled={disabled}
            prefix={currencyAffixes?.prefix ?? prefix}
            suffix={currencyAffixes?.suffix ?? suffix}
            customInput={CustomInput}
            onChange={() => null}
            autoComplete={autoComplete}
            multiline={multiline}
            required={required}
            min={min}
            max={max}
            // eslint-disable-next-line @typescript-eslint/no-unused-vars, no-unused-vars
            onValueChange={(values, sourceInfo) => {
                handleChange(values);
            }}
            onBlur={onBlur}
            onFocus={onFocus}
            errors={errors}
            placeholder={placeholder}
            keyValue={keyValue}
            label={label}
            decimalScale={decimalScale}
            thousandsGroupStyle={thousandsGroupStyle}
            thousandSeparator={thousandSeparator}
            decimalSeparator={decimalSeparator}
            data-test={dataTestId}
            size={size}
            showArrows={showArrows}
            showInfo={showInfo}
            onIncrement={handleIncrement}
            onDecrement={handleDecrement}
            hideError={hideError}
        />
    );
};
